-- Schema of database 'hh_patient' (PostgreSQL 16), generated by Hibernate from the JPA entities.
-- Reference only: the services create/update these tables automatically (spring.jpa.hibernate.ddl-auto=update).

CREATE TABLE public.medical_records (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    description character varying(2000),
    health_centre_name character varying(255),
    record_date date,
    record_type character varying(20) NOT NULL,
    recorded_by character varying(255),
    resident_id bigint NOT NULL,
    resident_name character varying(255),
    title character varying(150) NOT NULL,
    CONSTRAINT medical_records_record_type_check CHECK (((record_type)::text = ANY ((ARRAY['DIAGNOSIS'::character varying, 'LAB_RESULT'::character varying, 'VACCINATION'::character varying, 'PRESCRIPTION'::character varying, 'ALLERGY'::character varying, 'SURGERY'::character varying, 'ANTENATAL'::character varying, 'NOTE'::character varying])::text[])))
);
ALTER TABLE public.medical_records ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.medical_records_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.residents (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    aadhaar_last4 character varying(20),
    address character varying(255),
    allergies character varying(500),
    blood_group character varying(5),
    chronic_conditions character varying(500),
    current_medications character varying(500),
    date_of_birth date,
    disability boolean,
    emergency_contact_name character varying(255),
    emergency_contact_phone character varying(255),
    first_name character varying(80) NOT NULL,
    gender character varying(10) NOT NULL,
    height_cm double precision,
    household_number character varying(255),
    last_name character varying(80),
    phone character varying(255),
    pregnant boolean,
    resident_code character varying(20),
    status character varying(15),
    village character varying(80) NOT NULL,
    weight_kg double precision,
    CONSTRAINT residents_gender_check CHECK (((gender)::text = ANY ((ARRAY['MALE'::character varying, 'FEMALE'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT residents_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'MIGRATED'::character varying, 'DECEASED'::character varying])::text[])))
);
ALTER TABLE public.residents ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.residents_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.visits (
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    appointment_id bigint,
    attended_by character varying(255),
    blood_pressure character varying(255),
    diagnosis character varying(255),
    health_centre_id bigint,
    health_centre_name character varying(255),
    notes character varying(1000),
    pulse integer,
    reason character varying(255),
    resident_id bigint NOT NULL,
    resident_name character varying(255),
    temperaturec double precision,
    visit_date date NOT NULL,
    visit_type character varying(20) NOT NULL,
    weight_kg double precision,
    CONSTRAINT visits_visit_type_check CHECK (((visit_type)::text = ANY ((ARRAY['OPD'::character varying, 'EMERGENCY'::character varying, 'FOLLOW_UP'::character varying, 'HOME_VISIT'::character varying, 'HEALTH_CAMP'::character varying, 'ANTENATAL'::character varying, 'IMMUNIZATION'::character varying])::text[])))
);
ALTER TABLE public.visits ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.visits_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
ALTER TABLE ONLY public.medical_records
    ADD CONSTRAINT medical_records_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.residents
    ADD CONSTRAINT residents_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.residents
    ADD CONSTRAINT uki6p53tie62rdcao86alxqcjii UNIQUE (resident_code);
ALTER TABLE ONLY public.visits
    ADD CONSTRAINT visits_pkey PRIMARY KEY (id);
CREATE INDEX idxcwvv0nh8hmx9qnhawioegbwpj ON public.residents USING btree (village);
CREATE INDEX idxmnwh030dqp2m33pqt5xnof5i8 ON public.medical_records USING btree (resident_id);
CREATE INDEX idxnjlhwkcreinjkfbss8rtm99wc ON public.visits USING btree (resident_id);
